B.an2=new A.P("Xoay m\u1ed9t l\u1edbp","\u0110\u1eb7t ng\xf3n tay l\xean m\u1ed9t \xf4 c\u1ee7a kh\u1ed1i r\u1ed3i vu\u1ed1t theo h\u01b0\u1edbng mu\u1ed1n xoay. L\u1edbp ch\u1ee9a \xf4 \u0111\xf3 s\u1ebd xoay 90\xb0.")
B.amO=new A.P("Xoay g\xf3c nh\xecn",'Vu\u1ed1t \u1edf v\xf9ng tr\u1ed1ng b\xean ngo\xe0i kh\u1ed1i \u0111\u1ec3 xoay camera. Ch\u1ee5m/m\u1edf hai ng\xf3n \u0111\u1ec3 thu ph\xf3ng. N\xfat "\u0110\u1eb7t l\u1ea1i camera" \u0111\u01b0a v\u1ec1 g\xf3c m\u1eb7c \u0111\u1ecbnh.')
B.amE=new A.P("K\xfd hi\u1ec7u (n\xe2ng cao)",'D\xf9ng trong "\u0110i\u1ec1u khi\u1ec3n n\xe2ng cao" v\xe0 khi nh\u1eadp x\xe1o tr\u1ed9n. U (tr\xean), D (d\u01b0\u1edbi), L (tr\xe1i), R (ph\u1ea3i), F (tr\u01b0\u1edbc), B (sau). Kh\xf4ng d\u1ea5u = xoay theo chi\u1ec1u kim \u0111\u1ed3ng h\u1ed3 khi nh\xecn th\u1eb3ng v\xe0o m\u1eb7t \u0111\xf3; d\u1ea5u \' = ng\u01b0\u1ee3c chi\u1ec1u; 2 = xoay 180\xb0.')
B.anl=new A.P("\u0110i\u1ec3m",'\u0110i\u1ec3m = max(100, 5000 \u2212 5\xd7gi\xe2y \u2212 10\xd7s\u1ed1 n\u01b0\u1edbc) \u2212 150\xd7s\u1ed1 g\u1ee3i \xfd. D\xf9ng "T\u1ef1 gi\u1ea3i" th\xec v\xe1n \u0111\u01b0\u1ee3c ghi l\xe0 c\xf3 tr\u1ee3 gi\xfap, 0 \u0111i\u1ec3m v\xe0 kh\xf4ng l\xean b\u1ea3ng x\u1ebfp h\u1ea1ng.')
B.amF=new A.P("Tr\u1ee3 l\xfd gi\u1ea3i",'B\u1ea5m "G\u1ee3i \xfd": l\u1edbp c\u1ea7n xoay s\xe1ng l\xean tr\xean kh\u1ed1i k\xe8m m\u0169i t\xean ch\u1ec9 h\u01b0\u1edbng. Xoay \u0111\xfang th\xec g\u1ee3i \xfd t\u1ef1 sang b\u01b0\u1edbc sau; xoay kh\xe1c th\xec tr\u1ee3 l\xfd t\u1ef1 t\xednh l\u1ea1i theo kh\u1ed1i hi\u1ec7n t\u1ea1i. M\xe0n "Tr\u1ee3 l\xfd gi\u1ea3i" cho \u0111i t\u1eebng b\u01b0\u1edbc (Tr\u01b0\u1edbc/Ti\u1ebfp), t\u1ef1 gi\u1ea3i, t\u1ea1m d\u1eebng, \u0111\u1ed5i t\u1ed1c \u0111\u1ed9. H\u01b0\u1edbng d\u1eabn \u0111\u01b0\u1ee3c t\xednh ngay tr\xean m\xe1y, kh\xf4ng c\u1ea7n m\u1ea1ng, nh\u01b0ng kh\xf4ng ph\u1ea3i l\xfac n\xe0o c\u0169ng ng\u1eafn nh\u1ea5t.')
B.an7=new A.P("Ho\xe0n t\xe1c","Ho\xe0n t\xe1c/l\xe0m l\u1ea1i kh\xf4ng gi\u1edbi h\u1ea1n. M\u1ed7i l\u1ea7n ho\xe0n t\xe1c \u0111\u01b0\u1ee3c t\xednh l\xe0 m\u1ed9t l\u1ed7i trong th\u1ed1ng k\xea.")
B.a9X=s([B.anD,B.an2,B.amO,B.amE,B.anl,B.amF,B.an7],t.Wy)
B.an5=new A.P("Lu\u1eadt","\u0110i\u1ec1n s\u1ed1 1\u20139 sao cho m\u1ed7i h\xe0ng, m\u1ed7i c\u1ed9t v\xe0 m\u1ed7i kh\u1ed1i 3\xd73 ch\u1ee9a \u0111\u1ee7 1\u20139 kh\xf4ng l\u1eb7p l\u1ea1i.")
B.amc=new A.P("\u0110\u1ed9 kh\xf3",'M\u1ed7i \u0111\u1ec1 c\xf3 \u0111\xfang m\u1ed9t l\u1eddi gi\u1ea3i. \u0110\u1ed9 kh\xf3 \u0111\u01b0\u1ee3c ch\u1ea5m b\u1eb1ng k\u1ef9 thu\u1eadt c\u1ea7n d\xf9ng: D\u1ec5 = ch\u1ec9 c\u1ea7n "\xf4 duy nh\u1ea5t"; Trung b\xecnh = c\u1ea7n "v\u1ecb tr\xed duy nh\u1ea5t"; Kh\xf3 = c\u1ea7n lo\u1ea1i tr\u1eeb c\u1eb7p/kh\xf3a ho\u1eb7c th\u1eed-sai.')
B.anc=new A.P("Ghi ch\xfa",'B\u1eadt ch\u1ebf \u0111\u1ed9 "Ghi ch\xfa" \u0111\u1ec3 \u0111i\u1ec1n s\u1ed1 nh\u1ecf l\xe0m nh\xe1p. Khi \u0111i\u1ec1n s\u1ed1 ch\xednh, c\xe1c ghi ch\xfa tr\xf9ng trong c\xf9ng h\xe0ng/c\u1ed9t/kh\u1ed1i t\u1ef1 xo\xe1.')
B.amD=new A.P("\u0110i\u1ec3m","\u0110i\u1ec3m c\u01a1 b\u1ea3n D\u1ec5 1000 / Trung b\xecnh 2000 / Kh\xf3 3500, tr\u1eeb 2 \u0111i\u1ec3m m\u1ed7i gi\xe2y, 50 \u0111i\u1ec3m m\u1ed7i l\u1ed7i, 100 \u0111i\u1ec3m m\u1ed7i g\u1ee3i \xfd (t\u1ed1i thi\u1ec3u 100).")
B.aca=s([B.an5,B.amc,B.anc,B.amD],t.Wy)
